CREATE TABLE _settings_v16_operation_updates (
    sequence INTEGER PRIMARY KEY AUTOINCREMENT,
    request_id TEXT NOT NULL REFERENCES _settings_v16_operations(request_id),
    record TEXT NOT NULL CHECK(json_valid(record) AND json_type(record) = 'object' AND length(CAST(record AS BLOB)) <= 2048 AND coalesce(json_extract(record, '$.phase.phase') IN ('awaiting_confirmation', 'awaiting_action', 'in_flight', 'applying', 'finished'), 0)),
    occurred_at INTEGER NOT NULL CHECK(occurred_at >= 0 AND coalesce(json_extract(record, '$.updated_at') = occurred_at, 0)),
    CHECK(coalesce(json_extract(record, '$.phase.phase') != 'applying' OR (json_type(record, '$.write') = 'object' AND json_type(record, '$.write.resolution') = 'null' AND json_extract(record, '$.phase.expected_revision') = json_extract(record, '$.write.intent.before.revision') AND json_extract(record, '$.phase.revision') = json_extract(record, '$.write.intent.after.revision')), 0)),
    CHECK(json_type(record, '$.application') IS NULL OR coalesce(json_type(record, '$.application') = 'object' AND json_extract(record, '$.application.state') IN ('applied', 'restart_required', 'unavailable', 'failed') AND json_extract(record, '$.phase.phase') = 'finished' AND json_extract(record, '$.phase.result.state.kind') = 'pending_application' AND json_extract(record, '$.write.resolution') = 'applied', 0)),
    CHECK(json_type(record, '$.write') IS NULL OR coalesce(json_type(record, '$.write') = 'object' AND json_type(record, '$.write.intent') = 'object' AND json_extract(record, '$.write.intent.version') = 1 AND json_extract(record, '$.phase.phase') IN ('applying', 'finished') AND json_extract(record, '$.write.intent.before.revision') > 0 AND json_extract(record, '$.write.intent.before.revision') < 9223372036854775807 AND json_extract(record, '$.write.intent.after.revision') = json_extract(record, '$.write.intent.before.revision') + 1 AND length(json_extract(record, '$.write.intent.before.sha256')) = 64 AND json_extract(record, '$.write.intent.before.sha256') NOT GLOB '*[^0-9a-f]*' AND length(json_extract(record, '$.write.intent.after.sha256')) = 64 AND json_extract(record, '$.write.intent.after.sha256') NOT GLOB '*[^0-9a-f]*' AND (json_type(record, '$.write.resolution') = 'null' OR json_extract(record, '$.write.resolution') IN ('applied', 'not_applied')), 0))
) STRICT;

CREATE TABLE _settings_v16_native_requests (
    request_id TEXT PRIMARY KEY NOT NULL CHECK(length(request_id) = 36 AND lower(request_id) = request_id AND request_id NOT GLOB '*[^0-9a-f-]*' AND length(replace(request_id, '-', '')) = 32 AND substr(request_id, 9, 1) = '-' AND substr(request_id, 14, 1) = '-' AND substr(request_id, 19, 1) = '-' AND substr(request_id, 24, 1) = '-'),
    operation_id TEXT UNIQUE NOT NULL REFERENCES _settings_v16_operations(request_id),
    exact_request TEXT NOT NULL CHECK(json_valid(exact_request) AND json_type(exact_request) = 'object' AND length(CAST(exact_request AS BLOB)) <= 1024 AND coalesce(json_extract(exact_request, '$.native_request_id') = request_id AND json_extract(exact_request, '$.operation_id') = operation_id, 0))
) STRICT;

CREATE TABLE _settings_v16_agent_turns (
    command_id TEXT PRIMARY KEY NOT NULL CHECK(length(command_id)=36 AND command_id=lower(command_id) AND substr(command_id,9,1)='-' AND substr(command_id,14,1)='-' AND substr(command_id,19,1)='-' AND substr(command_id,24,1)='-' AND length(replace(command_id,'-',''))=32 AND replace(command_id,'-','') NOT GLOB '*[^0-9a-f]*' AND replace(command_id,'-','')!='00000000000000000000000000000000'),
    session_id TEXT NOT NULL REFERENCES _settings_v16_agent_sessions(session_id),
    task_id TEXT NOT NULL UNIQUE CHECK(length(task_id)=36 AND task_id=lower(task_id) AND substr(task_id,9,1)='-' AND substr(task_id,14,1)='-' AND substr(task_id,19,1)='-' AND substr(task_id,24,1)='-' AND length(replace(task_id,'-',''))=32 AND replace(task_id,'-','') NOT GLOB '*[^0-9a-f]*' AND replace(task_id,'-','')!='00000000000000000000000000000000'),
    phase TEXT NOT NULL CHECK(phase IN ('armed','unknown','settled','stopped_uncertain','stopped_unusable')),
    record TEXT NOT NULL CHECK(json_valid(record) AND json_type(record)='object' AND length(CAST(record AS BLOB))<=4096),
    remote_original_request_id TEXT CHECK(remote_original_request_id IS NULL OR (typeof(remote_original_request_id)='text' AND length(remote_original_request_id)=36 AND remote_original_request_id=lower(remote_original_request_id) COLLATE BINARY AND substr(remote_original_request_id,9,1)='-' AND substr(remote_original_request_id,14,1)='-' AND substr(remote_original_request_id,19,1)='-' AND substr(remote_original_request_id,24,1)='-' AND length(replace(remote_original_request_id,'-',''))=32 AND replace(remote_original_request_id,'-','') NOT GLOB '*[^0-9a-f]*' AND remote_original_request_id<>'00000000-0000-0000-0000-000000000000')),
    CHECK(coalesce(json_remove(record,'$.version','$.session_id','$.command_id','$.task_id','$.phase','$.attempt_id','$.model_attempts','$.tool_calls','$.charged_tokens','$.reserved_output_tokens','$.reported_input_tokens','$.reported_output_tokens','$.started_at','$.deadline','$.last_observed_wall','$.mutation_ids','$.provider_complete','$.usage_complete')='{}' AND json_extract(record,'$.version')=1 AND json_extract(record,'$.command_id')=command_id AND json_extract(record,'$.session_id')=session_id AND json_extract(record,'$.task_id')=task_id AND json_extract(record,'$.phase')=phase AND json_type(record,'$.model_attempts')='integer' AND json_extract(record,'$.model_attempts')>=0 AND json_extract(record,'$.model_attempts')<=4 AND json_type(record,'$.tool_calls')='integer' AND json_extract(record,'$.tool_calls')>=0 AND json_extract(record,'$.tool_calls')<=8 AND json_type(record,'$.charged_tokens')='integer' AND json_extract(record,'$.charged_tokens')>=0 AND json_type(record,'$.reserved_output_tokens')='integer' AND json_extract(record,'$.reserved_output_tokens')>=0 AND json_type(record,'$.reported_input_tokens')='integer' AND json_extract(record,'$.reported_input_tokens')>=0 AND json_type(record,'$.reported_output_tokens')='integer' AND json_extract(record,'$.reported_output_tokens')>=0 AND json_type(record,'$.started_at')='integer' AND json_extract(record,'$.started_at')>=0 AND json_type(record,'$.deadline')='integer' AND json_extract(record,'$.deadline')>=0 AND json_type(record,'$.last_observed_wall')='integer' AND json_extract(record,'$.last_observed_wall')>=0 AND json_extract(record,'$.deadline')>json_extract(record,'$.started_at') AND json_extract(record,'$.deadline')-json_extract(record,'$.started_at')<=120000 AND json_extract(record,'$.last_observed_wall')>=json_extract(record,'$.started_at') AND json_type(record,'$.mutation_ids')='array' AND json_array_length(record,'$.mutation_ids')<=8 AND json_type(record,'$.provider_complete') IN ('true','false') AND json_type(record,'$.usage_complete') IN ('true','false') AND ((json_extract(record,'$.model_attempts')=0 AND json_type(record,'$.attempt_id')='null' AND json_extract(record,'$.provider_complete')=0 AND json_extract(record,'$.usage_complete')=0) OR (json_extract(record,'$.model_attempts')>0 AND length(json_extract(record,'$.attempt_id'))=36 AND json_extract(record,'$.attempt_id')=lower(json_extract(record,'$.attempt_id')) AND substr(json_extract(record,'$.attempt_id'),9,1)='-' AND substr(json_extract(record,'$.attempt_id'),14,1)='-' AND substr(json_extract(record,'$.attempt_id'),19,1)='-' AND substr(json_extract(record,'$.attempt_id'),24,1)='-' AND length(replace(json_extract(record,'$.attempt_id'),'-',''))=32 AND replace(json_extract(record,'$.attempt_id'),'-','') NOT GLOB '*[^0-9a-f]*' AND replace(json_extract(record,'$.attempt_id'),'-','')!='00000000000000000000000000000000')) AND (json_extract(record,'$.tool_calls')>0 OR json_array_length(record,'$.mutation_ids')=0) AND (phase!='stopped_uncertain' OR (json_extract(record,'$.tool_calls')=0 AND json_array_length(record,'$.mutation_ids')=0 AND json_extract(record,'$.provider_complete')=0 AND json_extract(record,'$.usage_complete')=0)) AND (phase!='stopped_unusable' OR (json_extract(record,'$.tool_calls')=0 AND json_array_length(record,'$.mutation_ids')=0 AND json_extract(record,'$.provider_complete')=1)),0))
) STRICT;

CREATE TABLE _settings_v16_agent_cleanup (
    command_id TEXT PRIMARY KEY NOT NULL REFERENCES _settings_v16_agent_turns(command_id),
    attestation TEXT NOT NULL CHECK(json_valid(attestation) AND json_type(attestation)='object' AND length(CAST(attestation AS BLOB))<=512),
    CHECK(coalesce(json_remove(attestation,'$.version','$.command_id','$.exact_fence_sha256','$.owner_principal_id','$.attested_at','$.lost_ram_uncertainty_accepted')='{}' AND json_extract(attestation,'$.version')=1 AND json_extract(attestation,'$.command_id')=command_id AND length(json_extract(attestation,'$.exact_fence_sha256'))=64 AND json_extract(attestation,'$.exact_fence_sha256') NOT GLOB '*[^0-9a-f]*' AND length(json_extract(attestation,'$.owner_principal_id'))=36 AND json_extract(attestation,'$.owner_principal_id')=lower(json_extract(attestation,'$.owner_principal_id')) AND substr(json_extract(attestation,'$.owner_principal_id'),9,1)='-' AND substr(json_extract(attestation,'$.owner_principal_id'),14,1)='-' AND substr(json_extract(attestation,'$.owner_principal_id'),19,1)='-' AND substr(json_extract(attestation,'$.owner_principal_id'),24,1)='-' AND length(replace(json_extract(attestation,'$.owner_principal_id'),'-',''))=32 AND replace(json_extract(attestation,'$.owner_principal_id'),'-','') NOT GLOB '*[^0-9a-f]*' AND replace(json_extract(attestation,'$.owner_principal_id'),'-','')!='00000000000000000000000000000000' AND json_type(attestation,'$.attested_at')='integer' AND json_extract(attestation,'$.attested_at')>=0 AND json_type(attestation,'$.lost_ram_uncertainty_accepted')='true',0))
) STRICT;

