DELETE FROM sqlite_sequence WHERE name IN ('settings_operation_updates','_settings_v16_operation_updates');

INSERT INTO sqlite_sequence(rowid,name,seq) SELECT CAST(name AS INTEGER),n,value FROM _settings_v16_scratch WHERE kind='sequence' AND n='settings_operation_updates';

INSERT INTO _settings_v16_scratch(kind,name,ok) VALUES('assert','all_sequence_rows_types_values_and_rowids_exact',coalesce((NOT EXISTS(SELECT rowid,typeof(name),CAST(name AS BLOB),typeof(seq),CAST(seq AS BLOB) FROM sqlite_sequence EXCEPT SELECT CAST(name AS INTEGER),typeof(n),CAST(n AS BLOB),typeof(value),CAST(value AS BLOB) FROM _settings_v16_scratch WHERE kind='sequence') AND NOT EXISTS(SELECT CAST(name AS INTEGER),typeof(n),CAST(n AS BLOB),typeof(value),CAST(value AS BLOB) FROM _settings_v16_scratch WHERE kind='sequence' EXCEPT SELECT rowid,typeof(name),CAST(name AS BLOB),typeof(seq),CAST(seq AS BLOB) FROM sqlite_sequence)),0));

CREATE TABLE settings_remote_originals (
    host_id TEXT NOT NULL,
    actor_device_id TEXT NOT NULL REFERENCES devices(id),
    request_id TEXT NOT NULL,
    command_kind TEXT NOT NULL CHECK(command_kind IN ('chat_open','send','update')),
    identity TEXT NOT NULL CHECK(json_valid(identity) AND json_type(identity)='object'),
    link_kind TEXT CHECK(link_kind IN ('chat','turn','operation')),
    session_id TEXT REFERENCES settings_agent_sessions(session_id),
    turn_command_id TEXT REFERENCES settings_agent_turns(command_id),
    operation_id TEXT REFERENCES settings_operations(request_id),
    link TEXT CHECK(link IS NULL OR (json_valid(link) AND json_type(link)='object')),
    close TEXT CHECK(close IS NULL OR (json_valid(close) AND json_type(close)='object')),
    terminal TEXT CHECK(terminal IS NULL OR (json_valid(terminal) AND json_type(terminal)='object')),
    PRIMARY KEY(host_id,actor_device_id,request_id),
    CHECK(length(CAST(identity AS BLOB))+length(CAST(host_id AS BLOB))+length(CAST(actor_device_id AS BLOB))+length(CAST(request_id AS BLOB))+length(CAST(command_kind AS BLOB))<=1024),
    CHECK(coalesce(length(CAST(link AS BLOB)),0)+coalesce(length(CAST(link_kind AS BLOB)),0)+coalesce(length(CAST(session_id AS BLOB)),0)+coalesce(length(CAST(turn_command_id AS BLOB)),0)+coalesce(length(CAST(operation_id AS BLOB)),0)<=512),
    CHECK(close IS NULL OR length(CAST(close AS BLOB))<=128),
    CHECK(terminal IS NULL OR length(CAST(terminal AS BLOB))<=512)
) STRICT;

CREATE UNIQUE INDEX settings_remote_open_session ON settings_remote_originals(session_id) WHERE command_kind='chat_open' AND session_id IS NOT NULL;

CREATE UNIQUE INDEX settings_remote_send_turn ON settings_remote_originals(turn_command_id) WHERE turn_command_id IS NOT NULL;

CREATE UNIQUE INDEX settings_remote_update_operation ON settings_remote_originals(operation_id) WHERE operation_id IS NOT NULL;

CREATE INDEX settings_operation_history ON settings_operation_updates(request_id, sequence);

CREATE INDEX settings_agent_turn_session ON settings_agent_turns(session_id,command_id);

CREATE INDEX settings_agent_reserved_conversation ON settings_agent_sessions(lower(replace(replace(replace(replace(conversation_id,'urn:uuid:',''),'-',''),'{',''),'}','')));

CREATE INDEX settings_agent_reserved_create_command ON settings_agent_sessions(lower(replace(replace(replace(replace(create_command_id,'urn:uuid:',''),'-',''),'{',''),'}','')));

CREATE INDEX settings_agent_reserved_command ON settings_agent_turns(lower(replace(replace(replace(replace(command_id,'urn:uuid:',''),'-',''),'{',''),'}','')));

CREATE INDEX settings_agent_reserved_task ON settings_agent_turns(lower(replace(replace(replace(replace(task_id,'urn:uuid:',''),'-',''),'{',''),'}','')));

CREATE VIEW settings_agent_reserved_ids AS
    SELECT lower(replace(replace(replace(replace(conversation_id,'urn:uuid:',''),'-',''),'{',''),'}','')) AS id FROM settings_agent_sessions
    UNION ALL SELECT lower(replace(replace(replace(replace(create_command_id,'urn:uuid:',''),'-',''),'{',''),'}','')) FROM settings_agent_sessions
    UNION ALL SELECT lower(replace(replace(replace(replace(command_id,'urn:uuid:',''),'-',''),'{',''),'}','')) FROM settings_agent_turns
    UNION ALL SELECT lower(replace(replace(replace(replace(task_id,'urn:uuid:',''),'-',''),'{',''),'}','')) FROM settings_agent_turns;

