CREATE TRIGGER settings_agent_session_admission BEFORE INSERT ON settings_agent_sessions
BEGIN
    SELECT RAISE(ABORT,'Settings session tombstone capacity') WHERE (SELECT count(*) FROM settings_agent_sessions)>=1024;
    SELECT RAISE(ABORT,'Settings identity already belongs to ordinary storage') WHERE EXISTS(SELECT 1 FROM settings_agent_ordinary_ids WHERE id IN (lower(replace(replace(replace(replace(NEW.conversation_id,'urn:uuid:',''),'-',''),'{',''),'}','')),lower(replace(replace(replace(replace(NEW.create_command_id,'urn:uuid:',''),'-',''),'{',''),'}',''))));
    SELECT RAISE(ABORT,'Settings identity already reserved') WHERE EXISTS(SELECT 1 FROM settings_agent_reserved_ids WHERE id IN (lower(replace(replace(replace(replace(NEW.conversation_id,'urn:uuid:',''),'-',''),'{',''),'}','')),lower(replace(replace(replace(replace(NEW.create_command_id,'urn:uuid:',''),'-',''),'{',''),'}',''))));

    SELECT RAISE(ABORT,'paired Settings session identity already exists') WHERE (json_extract(NEW.reservation,'$.version')=2 AND EXISTS(SELECT 1 FROM settings_agent_sessions WHERE session_id=NEW.session_id OR conversation_id=NEW.conversation_id OR create_command_id=NEW.create_command_id)) OR EXISTS(SELECT 1 FROM settings_agent_sessions AS existing WHERE json_extract(existing.reservation,'$.version')=2 AND (existing.session_id=NEW.session_id COLLATE BINARY OR existing.conversation_id=NEW.conversation_id COLLATE BINARY OR existing.create_command_id=NEW.create_command_id COLLATE BINARY));
    SELECT RAISE(ABORT,'paired Settings session closed reservation') WHERE NOT coalesce(json_extract(NEW.reservation,'$.version')<>2 OR ((json_type(NEW.reservation,'$.version')='integer' AND json_extract(NEW.reservation,'$.version')>=2 AND json_extract(NEW.reservation,'$.version')<=2) AND json_extract(NEW.reservation,'$.session_id')=NEW.session_id COLLATE BINARY AND json_extract(NEW.reservation,'$.conversation_id')=NEW.conversation_id COLLATE BINARY AND json_extract(NEW.reservation,'$.create_command_id')=NEW.create_command_id COLLATE BINARY AND json_extract(NEW.reservation,'$.owner_principal_id')=json_extract(NEW.reservation,'$.host_id') COLLATE BINARY AND json_extract(NEW.reservation,'$.peer_keys.device_id')<>json_extract(NEW.reservation,'$.host_id') COLLATE BINARY AND (typeof(json_extract(NEW.reservation,'$.session_id'))='text' AND length(json_extract(NEW.reservation,'$.session_id'))=36 AND json_extract(NEW.reservation,'$.session_id')=lower(json_extract(NEW.reservation,'$.session_id')) COLLATE BINARY AND substr(json_extract(NEW.reservation,'$.session_id'),9,1)='-' AND substr(json_extract(NEW.reservation,'$.session_id'),14,1)='-' AND substr(json_extract(NEW.reservation,'$.session_id'),19,1)='-' AND substr(json_extract(NEW.reservation,'$.session_id'),24,1)='-' AND length(replace(json_extract(NEW.reservation,'$.session_id'),'-',''))=32 AND replace(json_extract(NEW.reservation,'$.session_id'),'-','') NOT GLOB '*[^0-9a-f]*' AND json_extract(NEW.reservation,'$.session_id')<>'00000000-0000-0000-0000-000000000000') AND (typeof(json_extract(NEW.reservation,'$.host_id'))='text' AND length(json_extract(NEW.reservation,'$.host_id'))=36 AND json_extract(NEW.reservation,'$.host_id')=lower(json_extract(NEW.reservation,'$.host_id')) COLLATE BINARY AND substr(json_extract(NEW.reservation,'$.host_id'),9,1)='-' AND substr(json_extract(NEW.reservation,'$.host_id'),14,1)='-' AND substr(json_extract(NEW.reservation,'$.host_id'),19,1)='-' AND substr(json_extract(NEW.reservation,'$.host_