CREATE TRIGGER settings_agent_session_no_update BEFORE UPDATE ON settings_agent_sessions BEGIN SELECT RAISE(ABORT,'Settings session reservation is immutable'); END;

CREATE TRIGGER settings_agent_session_no_delete BEFORE DELETE ON settings_agent_sessions BEGIN SELECT RAISE(ABORT,'Settings session reservation is retained'); END;

CREATE TRIGGER settings_agent_turn_admission BEFORE INSERT ON settings_agent_turns
BEGIN
    SELECT RAISE(ABORT,'Settings session turn capacity') WHERE (SELECT count(*) FROM settings_agent_turns WHERE session_id=NEW.session_id)>=8;
    SELECT RAISE(ABORT,'another Settings turn remains unresolved') WHERE EXISTS(SELECT 1 FROM settings_agent_turns AS t WHERE t.phase IN ('armed','unknown') AND NOT EXISTS(SELECT 1 FROM settings_agent_cleanup AS c WHERE c.command_id=t.command_id));
    SELECT RAISE(ABORT,'Settings turn requires original unspent Armed fence') WHERE NEW.phase!='armed' OR json_extract(NEW.record,'$.attempt_id') IS NOT NULL OR json_extract(NEW.record,'$.model_attempts')!=0 OR json_extract(NEW.record,'$.tool_calls')!=0 OR json_extract(NEW.record,'$.charged_tokens')!=0 OR json_extract(NEW.record,'$.reserved_output_tokens')!=0 OR json_extract(NEW.record,'$.reported_input_tokens')!=0 OR json_extract(NEW.record,'$.reported_output_tokens')!=0 OR json_extract(NEW.record,'$.provider_complete')!=0 OR json_extract(NEW.record,'$.usage_complete')!=0 OR json_array_length(NEW.record,'$.mutation_ids')!=0 OR json_extract(NEW.record,'$.last_observed_wall')!=json_extract(NEW.record,'$.started_at');
    SELECT RAISE(ABORT,'Settings turn is outside original session') WHERE NOT EXISTS(SELECT 1 FROM settings_agent_sessions AS s WHERE s.session_id=NEW.session_id AND json_extract(NEW.record,'$.started_at')>=json_extract(s.reservation,'$.created_at') AND json_extract(NEW.record,'$.deadline')<=json_extract(s.reservation,'$.expires_at'));
    SELECT RAISE(ABORT,'Settings identity already belongs to ordinary storage') WHERE EXISTS(SELECT 1 FROM settings_agent_ordinary_ids WHERE id IN (lower(replace(replace(replace(replace(NEW.command_id,'urn:uuid:',''),'-',''),'{',''),'}','')),lower(replace(replace(replace(replace(NEW.task_id,'urn:uuid:',''),'-',''),'{',''),'}',''))));
    SELECT RAISE(ABORT,'Settings identity already reserved') WHERE EXISTS(SELECT 1 FROM settings_agent_reserved_ids WHERE id IN (lower(replace(replace(replace(replace(NEW.command_id,'urn:uuid:',''),'-',''),'{',''),'}','')),lower(replace(replace(replace(replace(NEW.task_id,'urn:uuid:',''),'-',''),'{',''),'}',''))));

    SELECT RAISE(ABORT,'Settings turn original scalar version') WHERE NOT coalesce(EXISTS(SELECT 1 FROM settings_agent_sessions AS s WHERE s.session_id=NEW.session_id AND ((json_extract(s.reservation,'$.version')=1 AND NEW.remote_original_request_id IS NULL) OR (json_extract(s.reservation,'$.version')=2 AND (typeof(NEW.remote_original_request_id)='text' AND length(NEW.remote_original_request_id)=36 AND NEW.remote_original_request_id=lower(NEW.remote_original_request_id) COLLATE BINARY AND substr(NEW.remote_original_request_id,9,1)='-' AND substr(NEW.remote_original_request_id,14,1)='-' AND substr(NEW.remote_original_request_id,19,1)='-' AND substr(NEW.remote_original_request_id,24,1)='-' AND length(replace(NEW.remote_original_request_id,'-',''))=32 AND replace(NEW.remote_original_request_id,'-','') NOT GLOB '*[^0-9a-f]*' AND NEW.remote_original_request_id<>'00000000-0000-0000-0000-000000000000')))),0);
    SELECT RAISE(ABORT,'paired Settings turn identity already exists') WHERE NEW.remote_original_request_id IS NOT NULL AND EXISTS(SELECT 1 FROM settings_agent_turns WHERE command_id=NEW.command_id OR task_id=NEW.task_id);
    SELECT RAISE(ABORT,'paired Settings turn requires original Send') WHERE NOT coalesce(NEW.remote_original_request_id IS NULL OR EXISTS(SELECT 1 FROM settings_agent_sessions AS s JOIN settings_remote_originals AS o WHERE s.session_id=NEW.session_id AND (json_extract(s.reservation,'$.version')=2 AND o.host_id=json_extract(s.reservation,'$.host_id') AND o.actor_device_id=json_extract(s.reservation,'$.peer_keys.device_id') AND o.request_id=NEW.remote_original_request_id AND o.command_kind='send' AND json_extract(o.identity,'$.receipt')='accepted' AND json_extract(o.identity,'$.command.kind')='send' AND json_extract(o.identity,'$.command.chat_id')=s.session_id AND json_extract(o.identity,'$.command.provider_binding_sha256') IS json_extract(s.reservation,'$.provider_binding_sha256') COLLATE BINARY AND (json_extract(o.identity,'$.host_id') IS json_extract(s.reservation,'$.host_id') COLLATE BINARY AND json_extract(o.identity,'$.owner_principal_id') IS json_extract(s.reservation,'$.owner_principal_id') COLLATE BINARY AND json_extract(o.identity,'$.remote_parent_id') IS json_extract(s.reservation,'$.remote_parent_id') COLLATE BINARY AND json_extract(o.identity,'$.grant_id') IS json_extract(s.reservation,'$.grant_id') COLLATE BINARY AND json_extract(o.identity,'$.grant_revision') IS json_extract(s.reservation,'$.grant_revision') COLLATE BINARY AND json_extract(o.identity,'$.host_epoch') IS json_extract(s.reservation,'$.host_epoch') COLLATE BINARY AND json_extract(o.identity,'$.connection_epoch') IS json_extract(s.reservation,'$.connection_epoch') COLLATE BINARY AND json_extract(o.identity,'$.peer_keys.device_id') IS json_extract(s.reservation,'$.peer_keys.device_id') COLLATE BINARY AND json_extract(o.identity,'$.peer_keys.signing_key') IS json_extract(s.reservation,'$.peer_keys.signing_key') COLLATE BINARY AND json_extract(o.identity,'$.peer_keys.encryption_key') IS json_extract(s.reservation,'$.peer_keys.encryption_key') COLLATE BINARY) AND o.link IS NULL AND o.close IS NULL AND o.terminal IS NULL AND json_extract(o.identity,'$.admitted_at')<=json_extract(NEW.record,'$.started_at') AND json_extract(NEW.record,'$.started_at')<json_extract(o.identity,'$.expires_at'))),0);
    SELECT RAISE(ABORT,'paired Settings turn grant') WHERE NOT coalesce(NEW.remote_original_request_id IS NULL OR EXISTS(SELECT 1 FROM settings_agent_sessions AS s WHERE s.session_id=NEW.session_id AND EXISTS(SELECT 1 FROM transport_endpoint AS e JOIN devices AS d JOIN settings_grant_heads AS h JOIN settings_grant_versions AS g ON g.host_id=h.host_id AND g.device_id=h.device_id AND g.revision=h.revision WHERE e.singleton=1 AND e.device_id=json_extract(s.reservation,'$.host_id') COLLATE BINARY AND e.revoked_at IS NULL AND json_extract(e.configuration,'$.version')=1 AND json_extract(e.configuration,'$.keys.device_id')=e.device_id AND json_extract(e.configuration,'$.role.role')='host' AND d.id=json_extract(s.reservation,'$.peer_keys.device_id') COLLATE BINARY AND d.revoked_at IS NULL AND json_extract(d.public_identity,'$.version')=1 AND json_extract(d.public_identity,'$.keys.device_id')=d.id AND h.host_id=e.device_id AND h.device_id=d.id AND h.grant_id=json_extract(s.reservation,'$.grant_id') COLLATE BINARY AND h.revision=json_extract(s.reservation,'$.grant_revision') AND json_extract(g.record,'$.change.target.state.kind')='active' AND json_extract(g.record,'$.owner_principal_id')=json_extract(s.reservation,'$.owner_principal_id') COLLATE BINARY AND json_extract(g.record,'$.change.target.issued_at')<=json_extract(NEW.record,'$.started_at') AND json_extract(NEW.record,'$.started_at')<json_extract(g.record,'$.change.target.expires_at') AND json_extract(d.public_identity,'$.keys.signing_key') IS json_extract(s.reservation,'$.peer_keys.signing_key') COLLATE BINARY AND json_extract(g.record,'$.change.peer_keys.signing_key') IS json_extract(s.reservation,'$.peer_keys.signing_key') COLLATE BINARY AND json_extract(d.public_identity,'$.keys.encryption_key') IS json_extract(s.reservation,'$.peer_keys.encryption_key') COLLATE BINARY AND json_extract(g.record,'$.change.peer_keys.encryption_key') IS json_extract(s.reservation,'$.peer_keys.encryption_key') COLLATE BINARY AND json_extract(g.record,'$.change.target.state.session_consent.kind')='configured_provider')),0);
END;

CREATE TRIGGER settings_agent_turn_transition BEFORE UPDATE ON settings_agent_turns
BEGIN
    SELECT RAISE(ABORT,'Settings turn original identity is immutable') WHERE NEW.command_id!=OLD.command_id OR NEW.session_id!=OLD.session_id OR NEW.task_id!=OLD.task_id OR json_extract(NEW.record,'$.version')!=json_extract(OLD.record,'$.version') OR json_extract(NEW.record,'$.started_at')!=json_extract(OLD.record,'$.started_at') OR json_extract(NEW.record,'$.deadline')!=json_extract(OLD.record,'$.deadline');
    SELECT RAISE(ABORT,'Settings turn is already terminal or acknowledged') WHERE OLD.phase!='armed' OR EXISTS(SELECT 1 FROM settings_agent_cleanup WHERE command_id=OLD.command_id);
    SELECT RAISE(ABORT,'Settings conservative floor moved backward') WHERE json_extract(NEW.record,'$.model_attempts')<json_extract(OLD.record,'$.model_attempts') OR json_extract(NEW.record,'$.tool_calls')<json_extract(OLD.record,'$.tool_calls') OR json_extract(NEW.record,'$.charged_tokens')<json_extract(OLD.record,'$.charged_tokens') OR json_extract(NEW.record,'$.reserved_output_tokens')<json_extract(OLD.record,'$.reserved_output_tokens') OR json_extract(NEW.record,'$.reported_input_tokens')<json_extract(OLD.record,'$.reported_input_tokens') OR json_extract(NEW.record,'$.reported_output_tokens')<json_extract(OLD.record,'$.reported_output_tokens') OR json_extract(NEW.record,'$.last_observed_wall')<json_extract(OLD.record,'$.last_observed_wall');
    SELECT RAISE(ABORT,'Settings attempt identity and count disagree') WHERE (json_extract(NEW.record,'$.attempt_id') IS NOT json_extract(OLD.record,'$.attempt_id'))!=(json_extract(NEW.record,'$.model_attempts')>json_extract(OLD.record,'$.model_attempts'));
    SELECT RAISE(ABORT,'Settings current attempt completion moved backward') WHERE NEW.phase!='stopped_uncertain' AND json_extract(NEW.record,'$.attempt_id') IS json_extract(OLD.record,'$.attempt_id') AND (json_extract(NEW.record,'$.provider_complete')<json_extract(OLD.record,'$.provider_complete') OR json_extract(NEW.record,'$.usage_complete')<json_extract(OLD.record,'$.usage_complete'));
    SELECT RAISE(ABORT,'Settings fresh attempt cannot already be complete') WHERE json_extract(NEW.record,'$.attempt_id') IS NOT json_extract(OLD.record,'$.attempt_id') AND (json_extract(NEW.record,'$.provider_complete')!=0 OR json_extract(NEW.record,'$.usage_complete')!=0);
    SELECT RAISE(ABORT,'Settings mutation links cannot be forgotten') WHERE EXISTS(SELECT 1 FROM json_each(OLD.record,'$.mutation_ids') AS old WHERE NOT EXISTS(SELECT 1 FROM json_each(NEW.record,'$.mutation_ids') AS new WHERE new.value=old.value));
    SELECT RAISE(ABORT,'Settings mutation links must be canonical and unique') WHERE EXISTS(SELECT 1 FROM json_each(NEW.record,'$.mutation_ids') AS m WHERE m.type!='text' OR NOT (length(m.value)=36 AND m.value=lower(m.value) AND substr(m.value,9,1)='-' AND substr(m.value,14,1)='-' AND substr(m.value,19,1)='-' AND substr(m.value,24,1)='-' AND length(replace(m.value,'-',''))=32 AND replace(m.value,'-','') NOT GLOB '*[^0-9a-f]*' AND replace(m.value,'-','')!='00000000000000000000000000000000')) OR EXISTS(SELECT 1 FROM json_each(NEW.record,'$.mutation_ids') AS a JOIN json_each(NEW.record,'$.mutation_ids') AS b ON a.key<b.key WHERE a.value>=b.value);

    SELECT RAISE(ABORT,'Settings turn original link is immutable') WHERE NEW.remote_original_request_id IS NOT OLD.remote_original_request_id COLLATE BINARY;
END;

CREATE TRIGGER settings_agent_turn_no_delete BEFORE DELETE ON settings_agent_turns BEGIN SELECT RAISE(ABORT,'Settings turn fence is retained'); END;

CREATE TRIGGER settings_agent_cleanup_admission BEFORE INSERT ON settings_agent_cleanup
BEGIN
    SELECT RAISE(ABORT,'Settings cleanup does not bind original owner and fence') WHERE NOT EXISTS(SELECT 1 FROM settings_agent_turns AS t JOIN settings_agent_sessions AS s ON s.session_id=t.session_id WHERE t.command_id=NEW.command_id AND t.phase IN ('armed','unknown') AND ((json_extract(NEW.attestation,'$.owner_principal_id')=json_extract(s.reservation,'$.principal_id')) OR (json_extract(s.reservation,'$.version')=2 AND json_extract(NEW.attestation,'$.owner_principal_id')=json_extract(s.reservation,'$.owner_principal_id'))) AND json_extract(NEW.attestation,'$.attested_at')>=json_extract(t.record,'$.last_observed_wall'));
END;

CREATE TRIGGER settings_agent_cleanup_no_update BEFORE UPDATE ON settings_agent_cleanup BEGIN SELECT RAISE(ABORT,'Settings cleanup acknowledgement is immutable'); END;

CREATE TRIGGER settings_agent_cleanup_no_delete BEFORE DELETE ON settings_agent_cleanup BEGIN SELECT RAISE(ABORT,'Settings cleanup acknowledgement is retained'); END;

CREATE TRIGGER settings_agent_mutation_origin BEFORE INSERT ON settings_operations
WHEN EXISTS(SELECT 1 FROM settings_agent_turns AS t JOIN settings_agent_sessions AS s ON s.session_id=t.session_id JOIN json_each(t.record,'$.mutation_ids') AS m WHERE lower(replace(replace(replace(replace(m.value,'urn:uuid:',''),'-',''),'{',''),'}',''))=lower(replace(replace(replace(replace(NEW.request_id,'urn:uuid:',''),'-',''),'{',''),'}','')) AND NOT coalesce((json_extract(NEW.identity,'$.version')=1 AND json_extract(NEW.identity,'$.binding.request_id')=NEW.request_id AND json_extract(NEW.identity,'$.binding.principal_id')=json_extract(s.reservation,'$.principal_id') AND json_extract(NEW.identity,'$.binding.client_session_id')=json_extract(s.reservation,'$.native_session_id') AND json_extract(NEW.identity,'$.origin.kind')='settings_agent' AND json_extract(NEW.identity,'$.origin.session_id')=s.session_id AND json_extract(NEW.identity,'$.origin.native_session_id')=json_extract(s.reservation,'$.native_session_id')) OR (json_extract(NEW.identity,'$.version')=2 AND json_extract(s.reservation,'$.version')=2 AND json_extract(NEW.identity,'$.binding.request_id') IS NEW.request_id COLLATE BINARY AND json_extract(NEW.identity,'$.binding.principal_id') IS json_extract(s.reservation,'$.peer_keys.device_id') COLLATE BINARY AND json_extract(NEW.identity,'$.binding.client_session_id') IS json_extract(s.reservation,'$.remote_parent_id') COLLATE BINARY AND json_extract(NEW.identity,'$.binding.scope.kind')='host' AND json_extract(NEW.identity,'$.binding.scope.host_id') IS json_extract(s.reservation,'$.host_id') COLLATE BINARY AND json_extract(NEW.identity,'$.origin.kind')='paired_settings_agent' AND json_extract(NEW.identity,'$.origin.session_id') IS s.session_id COLLATE BINARY AND json_extract(NEW.identity,'$.origin.actor_device_id') IS json_extract(s.reservation,'$.peer_keys.device_id') COLLATE BINARY AND json_extract(NEW.identity,'$.origin.remote_parent_id') IS json_extract(s.reservation,'$.remote_parent_id') COLLATE BINARY AND json_extract(NEW.identity,'$.origin.grant_id') IS json_extract(s.reservation,'$.grant_id') COLLATE BINARY AND json_extract(NEW.identity,'$.origin.grant_revision') IS json_extract(s.reservation,'$.grant_revision') COLLATE BINARY AND json_extract(NEW.identity,'$.origin.host_epoch') IS json_extract(s.reservation,'$.host_epoch') COLLATE BINARY AND json_extract(NEW.identity,'$.origin.connection_epoch') IS json_extract(s.reservation,'$.connection_epoch') COLLATE BINARY),0))
BEGIN SELECT RAISE(ABORT,'Settings mutation identity belongs to another origin'); END;

CREATE TRIGGER settings_agent_existing_mutation_origin BEFORE UPDATE OF record ON settings_agent_turns
WHEN EXISTS(SELECT 1 FROM settings_agent_sessions AS s JOIN json_each(NEW.record,'$.mutation_ids') AS m JOIN settings_operations AS o ON o.request_id=m.value WHERE s.session_id=NEW.session_id AND NOT coalesce((json_extract(o.identity,'$.version')=1 AND json_extract(o.identity,'$.binding.request_id')=o.request_id AND json_extract(o.identity,'$.binding.principal_id')=json_extract(s.reservation,'$.principal_id') AND json_extract(o.identity,'$.binding.client_session_id')=json_extract(s.reservation,'$.native_session_id') AND json_extract(o.identity,'$.origin.kind')='settings_agent' AND json_extract(o.identity,'$.origin.session_id')=s.session_id AND json_extract(o.identity,'$.origin.native_session_id')=json_extract(s.reservation,'$.native_session_id')) OR (json_extract(o.identity,'$.version')=2 AND json_extract(s.reservation,'$.version')=2 AND json_extract(o.identity,'$.binding.request_id') IS o.request_id COLLATE BINARY AND json_extract(o.identity,'$.binding.principal_id') IS json_extract(s.reservation,'$.peer_keys.device_id') COLLATE BINARY AND json_extract(o.identity,'$.binding.client_session_id') IS json_extract(s.reservation,'$.remote_parent_id') COLLATE BINARY AND json_extract(o.identity,'$.binding.scope.kind')='host' AND json_extract(o.identity,'$.binding.scope.host_id') IS json_extract(s.reservation,'$.host_id') COLLATE BINARY AND json_extract(o.identity,'$.origin.kind')='paired_settings_agent' AND json_extract(o.identity,'$.origin.session_id') IS s.session_id COLLATE BINARY AND json_extract(o.identity,'$.origin.actor_device_id') IS json_extract(s.reservation,'$.peer_keys.device_id') COLLATE BINARY AND json_extract(o.identity,'$.origin.remote_parent_id') IS json_extract(s.reservation,'$.remote_parent_id') COLLATE BINARY AND json_extract(o.identity,'$.origin.grant_id') IS json_extract(s.reservation,'$.grant_id') COLLATE BINARY AND json_extract(o.identity,'$.origin.grant_revision') IS json_extract(s.reservation,'$.grant_revision') COLLATE BINARY AND json_extract(o.identity,'$.origin.host_epoch') IS json_extract(s.reservation,'$.host_epoch') COLLATE BINARY AND json_extract(o.identity,'$.origin.connection_epoch') IS json_extract(s.reservation,'$.connection_epoch') COLLATE BINARY),0))
BEGIN SELECT RAISE(ABORT,'Settings mutation identity belongs to another origin'); END;

