on_extract(NEW.identity,'$.grant_id') IS json_extract(o.identity,'$.origin.grant_id') COLLATE BINARY AND json_extract(NEW.identity,'$.grant_revision') IS json_extract(o.identity,'$.origin.grant_revision') COLLATE BINARY AND json_extract(NEW.identity,'$.host_epoch') IS json_extract(o.identity,'$.origin.host_epoch') COLLATE BINARY AND json_extract(NEW.identity,'$.connection_epoch') IS json_extract(o.identity,'$.origin.connection_epoch') COLLATE BINARY AND json_extract(NEW.identity,'$.issued_at') IS json_extract(o.identity,'$.binding.issued_at') COLLATE BINARY AND json_extract(NEW.identity,'$.expires_at') IS json_extract(o.identity,'$.binding.expires_at') COLLATE BINARY AND json_extract(NEW.identity,'$.command.expected_settings_revision') IS json_extract(o.identity,'$.binding.expected_revision') COLLATE BINARY AND json_extract(NEW.identity,'$.command.kind')='update' AND json_extract(NEW.identity,'$.receipt')='accepted' AND ((json_type(NEW.identity,'$.command.enabled')='null' AND NOT EXISTS(SELECT 1 FROM json_each(o.identity,'$.target.request.changes') AS c WHERE json_extract(c.value,'$.key')='memory.embeddings.enabled')) OR (json_type(NEW.identity,'$.command.enabled')<>'null' AND EXISTS(SELECT 1 FROM json_each(o.identity,'$.target.request.changes') AS c WHERE json_extract(c.value,'$.key')='memory.embeddings.enabled' AND json_extract(c.value,'$.value.value') IS json_extract(NEW.identity,'$.command.enabled')))) AND ((json_type(NEW.identity,'$.command.dimensions')='null' AND NOT EXISTS(SELECT 1 FROM json_each(o.identity,'$.target.request.changes') AS c WHERE json_extract(c.value,'$.key')='memory.embeddings.dimensions')) OR (json_type(NEW.identity,'$.command.dimensions')<>'null' AND EXISTS(SELECT 1 FROM json_each(o.identity,'$.target.request.changes') AS c WHERE json_extract(c.value,'$.key')='memory.embeddings.dimensions' AND ((json_extract(NEW.identity,'$.command.dimensions.kind')='backend_default' AND json_type(c.value,'$.value.value')='null') OR (json_extract(NEW.identi