CREATE TRIGGER settings_remote_originals_no_delete BEFORE DELETE ON settings_remote_originals
BEGIN
    SELECT RAISE(ABORT,'remote Settings original retirement is permanent') WHERE 1;
END;

CREATE TRIGGER settings_remote_session_install AFTER INSERT ON settings_agent_sessions
WHEN json_extract(NEW.reservation,'$.version')=2
BEGIN
    UPDATE settings_remote_originals SET link_kind='chat',session_id=NEW.session_id,link=json_object('kind','chat','session_id',NEW.session_id) WHERE host_id=json_extract(NEW.reservation,'$.host_id') AND actor_device_id=json_extract(NEW.reservation,'$.peer_keys.device_id') AND request_id=json_extract(NEW.reservation,'$.open_request_id') AND command_kind='chat_open' AND link IS NULL AND close IS NULL AND terminal IS NULL;
    SELECT RAISE(ABORT,'remote Settings original install did not bind exactly one row') WHERE changes()<>1;
END;

CREATE TRIGGER settings_remote_turn_install AFTER INSERT ON settings_agent_turns
WHEN NEW.remote_original_request_id IS NOT NULL
BEGIN
    UPDATE settings_remote_originals SET link_kind='turn',session_id=NEW.session_id,turn_command_id=NEW.command_id,link=json_object('kind','turn','session_id',NEW.session_id,'command_id',NEW.command_id) WHERE request_id=NEW.remote_original_request_id AND command_kind='send' AND EXISTS(SELECT 1 FROM settings_agent_sessions AS s WHERE s.session_id=NEW.session_id AND host_id=json_extract(s.reservation,'$.host_id') AND actor_device_id=json_extract(s.reservation,'$.peer_keys.device_id')) AND link IS NULL AND close IS NULL AND terminal IS NULL;
    SELECT RAISE(ABORT,'remote Settings original install did not bind exactly one row') WHERE changes()<>1;
END;

