CREATE TRIGGER settings_remote_operation_install AFTER INSERT ON settings_operations
WHEN json_extract(NEW.identity,'$.version')=2 AND json_extract(NEW.identity,'$.origin.kind')='paired_settings'
BEGIN
    UPDATE settings_remote_originals SET link_kind='operation',operation_id=NEW.request_id,link=json_object('kind','operation','operation_id',NEW.request_id) WHERE host_id=json_extract(NEW.identity,'$.binding.scope.host_id') AND actor_device_id=json_extract(NEW.identity,'$.origin.actor_device_id') AND request_id=NEW.request_id AND command_kind='update' AND link IS NULL AND close IS NULL AND terminal IS NULL;
    SELECT RAISE(ABORT,'remote Settings original install did not bind exactly one row') WHERE changes()<>1;
END;

CREATE TRIGGER settings_remote_update_admission BEFORE INSERT ON settings_operation_updates
