    SELECT RAISE(ABORT,'paired Settings update closed metadata') WHERE NOT coalesce(((json_type(NEW.record,'$')='object' AND (SELECT count(*) FROM json_each(NEW.record,'$'))=3 AND (SELECT count(DISTINCT key) FROM json_each(NEW.record,'$'))=3 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.record,'$') WHERE key NOT IN ('phase','observation','updated_at'))) OR (json_type(NEW.record,'$')='object' AND (SELECT count(*) FROM json_each(NEW.record,'$'))=4 AND (SELECT count(DISTINCT key) FROM json_each(NEW.record,'$'))=4 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.record,'$') WHERE key NOT IN ('phase','observation','updated_at','write'))) OR (json_type(NEW.record,'$')='object' AND (SELECT count(*) FROM json_each(NEW.record,'$'))=5 AND (SELECT count(DISTINCT key) FROM json_each(NEW.record,'$'))=5 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.record,'$') WHERE key NOT IN ('phase','observation','updated_at','write','application')))),0);
