    SELECT RAISE(ABORT,'paired Settings update exact finished state') WHERE NOT coalesce(json_extract(NEW.record,'$.phase.phase')<>'finished' OR (((json_type(NEW.record,'$.phase.result.state')='object' AND (SELECT count(*) FROM json_each(NEW.record,'$.phase.result.state'))=1 AND (SELECT count(DISTINCT key) FROM json_each(NEW.record,'$.phase.result.state'))=1 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.record,'$.phase.result.state') WHERE key NOT IN ('kind'))) AND json_extract(NEW.record,'$.phase.result.state.kind') IN ('host_action_required','unknown','cancelled')) OR ((json_type(NEW.record,'$.phase.result.state')='object' AND (SELECT count(*) FROM json_each(NEW.record,'$.phase.result.state'))=2 AND (SELECT count(DISTINCT key) FROM json_each(NEW.record,'$.phase.result.state'))=2 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.record,'$.phase.result.state') WHERE key NOT IN ('kind','revision'))) AND json_extract(NEW.record,'$.phase.result.state.kind') IN ('applied','pending_application','restart_required') AND (json_type(NEW.record,'$.phase.result.state.revision')='integer' AND json_extract(NEW.record,'$.phase.result.state.revision')>=1 AND json_extract(NEW.record,'$.phase.result.state.revision')<=9223372036854775807)) OR ((json_type(NEW.record,'$.phase.result.state')='object' AND (SELECT count(*) FROM json_each(NEW.record,'$.phase.result.state'))=2 AND (SELECT count(DISTINCT key) FROM json_each(NEW.record,'$.phase.result.state'))=2 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.record,'$.phase.result.state') WHERE key NOT IN ('kind','observed_revision'))) AND json_extract(NEW.record,'$.phase.result.state.kind')='conflict' AND (json_type(NEW.record,'$.phase.result.state.observed_revision')='integer' AND json_extract(NEW.record,'$.phase.result.state.observed_revision')>=1 AND json_extract(NEW.record,'$.phase.result.state.observed_revision')<=9223372036854775807)) OR ((json_type(NEW.record,'$.phase.result.state')='object' AND (SELECT count(*) FROM json_each(NEW.record,'$.phase.result.state'))=2 AND (SELECT count(DISTINCT key) FROM json_each(NEW.record,'$.phase.result.state'))=2 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.record,'$.phase.result.state') WHERE key NOT IN ('kind','reason'))) AND json_extract(NEW.record,'$.phase.result.state.kind')='unavailable' AND json_extract(NEW.record,'$.phase.result.state.reason') IN ('host_offline','provider_unavailable','embedding_metadata_unavailable','embedding_boundary_unavailable','native_action_unavailable','permission_denied','expired')) OR ((json_type(NEW.record,'$.phase.result.state')='object' AND (SELECT count(*) FROM json_each(NEW.record,'$.phase.result.state'))=2 AND (SELECT count(DISTINCT key) FROM json_each(NEW.record,'$.phase.result.state'))=2 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.record,'$.phase.result.state') WHERE key NOT IN ('kind','reason'))) AND json_extract(NEW.record,'$.phase.result.state.kind')='failed' AND json_extract(NEW.record,'$.phase.result.state.reason') IN ('invalid_request','storage','apply_failed','native_action_failed'))),0);
    SELECT RAISE(ABORT,'paired Settings update exact write') WHERE NOT coalesce(json_type(NEW.record,'$.write') IS NULL OR ((json_type(NEW.record,'$.write')='object' AND (SELECT count(*) FROM json_each(NEW.record,'$.write'))=2 AND (SELECT count(DISTINCT key) FROM json_each(NEW.record,'$.write'))=2 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.record,'$.write') WHERE key NOT IN ('intent','resolution'))) AND (json_type(NEW.record,'$.write.intent')='object' AND (SELECT count(*) FROM json_each(NEW.record,'$.write.intent'))=8 AND (SELECT count(DISTINCT key) FROM json_each(NEW.record,'$.write.intent'))=8 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.record,'$.write.intent') WHERE key NOT IN ('version','before','after','native_request_id','changed_keys','memory_changed','selection_changed','restart_required'))) AND (json_type(NEW.record,'$.write.intent.version')='integer' AND json_extract(NEW.record,'$.write.intent.version')>=1 AND json_extract(NEW.record,'$.write.intent.version')<=1) AND (json_type(NEW.record,'$.write.intent.before')='object' AND (SELECT count(*) FROM json_each(NEW.record,'$.write.intent.before'))=2 AND (SELECT count(DISTINCT key) FROM json_each(NEW.record,'$.write.intent.before'))=2 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.record,'$.write.intent.before') WHERE key NOT IN ('revision','sha256'))) AND (json_type(NEW.record,'$.write.intent.after')='object' AND (SELECT count(*) FROM json_each(NEW.record,'$.write.intent.after'))=2 AND (SELECT count(DISTINCT key) FROM json_each(NEW.record,'$.write.intent.after'))=2 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.record,'$.write.intent.after') WHERE key NOT IN ('revision','sha256'))) AND (json_type(NEW.record,'$.write.intent.before.revision')='integer' AND json_extract(NEW.record,'$.write.intent.before.revision')>=1 AND json_extract(NEW.record,'$.write.intent.before.revision')<=9223372036854775806) AND (json_type(NEW.record,'$.write.intent.after.revision')='integer' AND json_extract(NEW.record,'$.write.intent.after.revision')>=2 AND json_extract(NEW.record,'$.write.intent.after.revision')<=9223372036854775807) AND json_extract(NEW.record,'$.write.intent.after.revision')=json_extract(NEW.record,'$.write.intent.before.revision')+1 AND (typeof(json_extract(NEW.record,'$.write.intent.before.sha256'))='text' AND length(json_extract(NEW.record,'$.write.intent.before.sha256'))=64 AND json_extract(NEW.record,'$.write.intent.before.sha256') NOT GLOB '*[^0-9a-f]*') AND (typeof(json_extract(NEW.record,'$.write.intent.after.sha256'))='text' AND length(json_extract(NEW.record,'$.write.intent.after.sha256'))=64 AND json_extract(NEW.record,'$.write.intent.after.sha256') NOT GLOB '*[^0-9a-f]*') AND json_type(NEW.record,'$.write.intent.native_request_id')='null' AND json_type(NEW.record,'$.write.intent.changed_keys')='array' AND json_array_length(NEW.record,'$.write.intent.changed_keys') BETWEEN 1 AND 2 AND json_type(NEW.record,'$.write.intent.memory_changed') IN ('true','false') AND json_type(NEW.record,'$.write.intent.selection_changed')='false' AND json_type(NEW.record,'$.write.intent.restart_required')='false' AND (json_type(NEW.record,'$.write.resolution')='null' OR json_extract(NEW.record,'$.write.resolution') IN ('applied','not_applied')) AND NOT EXISTS(SELECT 1 FROM json_each(NEW.record,'$.write.intent.changed_keys') AS a JOIN json_each(NEW.record,'$.write.intent.changed_keys') AS b ON a.key<b.key WHERE a.value<=b.value COLLATE BINARY)),0);
    SELECT RAISE(ABORT,'paired Settings update exact application') WHERE NOT coalesce(json_type(NEW.record,'$.application') IS NULL OR (((json_type(NEW.record,'$.application')='object' AND (SELECT count(*) FROM json_each(NEW.record,'$.application'))=1 AND (SELECT count(DISTINCT key) FROM json_each(NEW.record,'$.application'))=1 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.record,'$.application') WHERE key NOT IN ('state'))) AND json_extract(NEW.record,'$.application.state') IN ('applied','restart_required')) OR ((json_type(NEW.record,'$.application')='object' AND (SELECT count(*) FROM json_each(NEW.record,'$.application'))=2 AND (SELECT count(DISTINCT key) FROM json_each(NEW.record,'$.application'))=2 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.record,'$.application') WHERE key NOT IN ('state','reason'))) AND json_extract(NEW.record,'$.application.state')='unavailable' AND json_extract(NEW.record,'$.application.reason') IN ('host_offline','provider_unavailable','embedding_metadata_unavailable','embedding_boundary_unavailable','native_action_unavailable','permission_denied','expired')) OR ((json_type(NEW.record,'$.application')='object' AND (SELECT count(*) FROM json_each(NEW.record,'$.application'))=2 AND (SELECT count(DISTINCT key) FROM json_each(NEW.record,'$.application'))=2 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.record,'$.application') WHERE key NOT IN ('state','reason'))) AND json_extract(NEW.record,'$.application.state')='failed' AND json_extract(NEW.record,'$.application.reason') IN ('invalid_request','storage','apply_failed','native_action_failed'))),0);
    SELECT RAISE(ABORT,'paired Settings update original scope and keys') WHERE NOT coalesce(EXISTS(SELECT 1 FROM settings_operations AS o WHERE o.request_id=NEW.request_id AND json_extract(NEW.record,'$.updated_at')>=o.created_at AND (json_type(NEW.record,'$.write') IS NULL OR (json_extract(NEW.record,'$.write.intent.before.revision')=json_extract(o.identity,'$.binding.expected_revision') AND json_array_length(NEW.record,'$.write.intent.changed_keys')=json_array_length(o.identity,'$.target.request.changes'))) AND (json_extract(NEW.record,'$.phase.phase')<>'finished' OR json_extract(NEW.record,'$.phase.result.scope.host_id') IS json_extract(o.identity,'$.binding.scope.host_id') COLLATE BINARY) AND NOT EXISTS(SELECT 1 FROM json_each(NEW.record,'$.write.intent.changed_keys') AS k WHERE k.type<>'text' OR k.value NOT IN ('memory.embeddings.enabled','memory.embeddings.dimensions') OR NOT EXISTS(SELECT 1 FROM json_each(o.identity,'$.target.request.changes') AS item WHERE json_extract(item.value,'$.key')=k.value COLLATE BINARY))),0);
END;

CREATE TRIGGER settings_remote_native_request_denied BEFORE INSERT ON settings_native_requests
WHEN EXISTS(SELECT 1 FROM settings_operations AS o WHERE o.request_id=NEW.operation_id AND json_extract(o.identity,'$.version')=2)
BEGIN
    SELECT RAISE(ABORT,'paired Settings cannot create native requests') WHERE 1;
END;

